// Design tokens: JSON source -> CSS custom properties, plus WCAG contrast maths.

const block = (selector, vars) => `${selector} {\n${Object.entries(vars).map(([k, v]) => `  ${k}: ${v};`).join('\n')}\n}\n`

export const buildCss = ({ base, tenants }) =>
  [
    '/* GENERATED by scripts/build-tokens.mjs from tokens/tokens.json. Do not edit by hand.',
    '   Components consume only these custom properties, never raw values. White-label',
    '   tenants override the brand layer via [data-tenant]. */',
    block(':root', base),
    ...Object.entries(tenants).map(([name, vars]) => block(`[data-tenant='${name}']`, vars)),
  ].join('\n')

const channel = (hex, i) => {
  const c = parseInt(hex.slice(1 + i * 2, 3 + i * 2), 16) / 255
  return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4
}
const luminance = (hex) => 0.2126 * channel(hex, 0) + 0.7152 * channel(hex, 1) + 0.0722 * channel(hex, 2)

// WCAG 2.x contrast ratio between two #rrggbb colours.
export const contrast = (a, b) => {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x)
  return (hi + 0.05) / (lo + 0.05)
}

// A tenant sees the base tokens with its own overrides on top.
export const resolveTenant = ({ base, tenants }, tenant) => ({ ...base, ...(tenants[tenant] ?? {}) })
